function radar(v,ref){const cats=['BAT','ATT','R','S-O','B-P'],n=cats.length,W=300,H=270,cx=W/2,cy=H/2+4,R=76;const pt=(k,f)=>{const a=-Math.PI/2+k*2*Math.PI/n;return[cx+Math.cos(a)*R*f,cy+Math.sin(a)*R*f]};const poly=a=>a.map(q=>q[0].toFixed(1)+','+q[1].toFixed(1)).join(' ');let g=`<svg viewBox='0 0 ${W} ${H}' role='img' aria-label='Positivit\u00E0 per fondamentale'>`;[.25,.5,.75,1].forEach(f=>{g+=`<polygon points='${poly(cats.map((c,k)=>pt(k,f)))}' fill='none' stroke='var(--line)' stroke-width='1'/>`;g+=`<text x='${cx+3}' y='${cy-R*f+10}'>${Math.round(f*100)}</text>`});cats.forEach((c,k)=>{const e=pt(k,1);g+=`<line x1='${cx}' y1='${cy}' x2='${e[0].toFixed(1)}' y2='${e[1].toFixed(1)}' stroke='var(--line)' stroke-width='1'/>`});g+=`<polygon points='${poly(ref.map((r,k)=>pt(k,r)))}' fill='none' stroke='var(--mut)' stroke-width='1.5' stroke-dasharray='4 3'/>`;if(v.some(x=>x!==null)){g+=`<polygon points='${poly(v.map((x,k)=>pt(k,x||0)))}' fill='var(--lib)' fill-opacity='.22' stroke='var(--lib)' stroke-width='2.5' stroke-linejoin='round'/>`;v.forEach((x,k)=>{if(x!==null){const q=pt(k,x);g+=`<circle cx='${q[0].toFixed(1)}' cy='${q[1].toFixed(1)}' r='3.5' fill='var(--lib)'/>`}})}else g+=`<text x='${cx}' y='${cy+3}' text-anchor='middle'>Nessun dato</text>`;cats.forEach((c,k)=>{const e=pt(k,1.2),al=Math.abs(e[0]-cx)<4?'middle':e[0]>cx?'start':'end',y=e[1]+(k===0?-4:k===2||k===3?12:4);g+=`<text class='vl' x='${e[0].toFixed(1)}' y='${y.toFixed(1)}' text-anchor='${al}'>${c}${v[k]!==null?' ('+pv(v[k])+'%)':''}</text>`});g+='</svg>';return g+`<div class='leg'><span><i class='sw' style='background:var(--lib)'></i>BAT, ATT, R: azioni con + su tutte le azioni \u00B7 S-O side-out \u00B7 B-P break point</span><span><i class='sw' style='background:var(--mut)'></i>obiettivo</span></div>`}
