function trendSvg(tr){if(!tr.length)return `<p class='note'>Nessun punto registrato.</p>`;const W=300,H=250,pl=30,pr=10,pt=14,pb=34,pw=W-pl-pr,ph=H-pt-pb;let n=1,m=2;tr.forEach(t=>{n=Math.max(n,t.p.length-1);t.p.forEach(v=>{m=Math.max(m,Math.abs(v))})});const ys=Math.max(1,Math.round(nice(m/2)));m=Math.ceil(m/ys)*ys;const X=i=>pl+i/n*pw,Y=v=>pt+(m-v)/(2*m)*ph,xs=Math.max(1,Math.round(nice(n/5)));let nsub=0,g=`<svg viewBox='0 0 ${W} ${H}' role='img' aria-label='Andamento del punteggio'>`;for(let v=-m;v<=m;v+=ys)g+=`<line x1='${pl}' x2='${W-pr}' y1='${Y(v).toFixed(1)}' y2='${Y(v).toFixed(1)}' stroke='${v===0?'var(--mut)':'var(--line)'}' stroke-width='${v===0?2:1}'/><text x='${pl-4}' y='${(Y(v)+3).toFixed(1)}' text-anchor='end'>${v>0?'+'+v:v}</text>`;for(let i=0;i<=n;i+=xs)g+=`<text x='${X(i).toFixed(1)}' y='${H-18}' text-anchor='middle'>${i}</text>`;g+=`<text x='${pl+pw/2}' y='${H-4}' text-anchor='middle'>punti giocati nel set</text>`;tr.forEach(t=>{const c=SETC[t.k-1],pts=t.p.map((v,i)=>X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' '),e=t.p.length-1;if(tr.length===1)g+=`<polygon points='${X(0).toFixed(1)},${Y(0).toFixed(1)} ${pts} ${X(e).toFixed(1)},${Y(0).toFixed(1)}' fill='${c}' fill-opacity='.15'/>`;g+=`<polyline points='${pts}' fill='none' stroke='${c}' stroke-width='2.2' stroke-linejoin='round' stroke-linecap='round'/><circle cx='${X(e).toFixed(1)}' cy='${Y(t.p[e]).toFixed(1)}' r='3' fill='${c}'/>`;const sb={};(S.subs||[]).forEach(u=>{if(u[0]===t.k){const q=Math.min(u[1],e);(sb[q]=sb[q]||[]).push((S.names[u[2]]||'?')+' \u2192 '+(S.names[u[3]]||'?'))}});Object.keys(sb).forEach(q=>{g+=`<circle cx='${X(+q).toFixed(1)}' cy='${Y(t.p[q]).toFixed(1)}' r='4.5' fill='var(--bg,#fff)' stroke='${c}' stroke-width='2.2'><title>Cambio: ${esc(sb[q].join(', '))}</title></circle>`;nsub++})});return g+'</svg>'+`<div class='leg'>`+(tr.length>1?tr.map(t=>`<span><i class='sw' style='background:${SETC[t.k-1]}'></i>Set ${t.k}</span>`).join(''):'')+`<span>sopra lo 0: in vantaggio ${esc(teamN())}</span>${nsub?`<span><i class='sw sub'></i>cambio (tocca il cerchio)</span>`:''}</div>`}
function errs(s){return bars(['BT','ATT','R','M','Falli'],setList(s).map(k=>{const T=teamSt(k);return{name:'Set '+k,c:SETC[k-1],v:[T.eBT,T.eATT,T.eR,T.eM,T.fal]}}),0)+`<div class='leg'><span>BT battuta \u00B7 ATT attacco \u00B7 R ricezione \u00B7 M muro</span></div>`}
function recv(s){const r=S.pl.map((p,i)=>({n:S.names[i],l:isL(i),r:st(i,s)})).filter(x=>x.r.nR>0).map(x=>({n:x.n,l:x.l,p:x.r.rP,t:x.r.nR,v:x.r.rP/x.r.nR})).sort((a,b)=>b.v-a.v||b.t-a.t);if(!r.length)return `<p class='note'>Nessuna ricezione registrata.</p>`;const W=300,rh=24,pt=14,pl=84,pr=70,pw=W-pl-pr,H=pt+r.length*rh+6,tx=pl+pw*TGT[2];let g=`<svg viewBox='0 0 ${W} ${H}' role='img' aria-label='Ricezione positiva per giocatrice'>`;[0,.5,1].forEach(f=>{g+=`<line x1='${pl+pw*f}' x2='${pl+pw*f}' y1='${pt-4}' y2='${H-6}' stroke='var(--line)' stroke-width='1'/><text x='${pl+pw*f}' y='8' text-anchor='middle'>${f*100}</text>`});r.forEach((x,k)=>{const y=pt+k*rh,mx=x.l?9:11,nm=x.n.length>mx?x.n.slice(0,mx-1)+'\u2026':x.n;g+=`<text x='${pl-5}' y='${y+rh/2+3}' text-anchor='end'>${esc(nm)}${x.l?' L':''}</text><rect x='${pl}' y='${y+4}' width='${Math.max(pw*x.v,x.v?2:0)}' height='${rh-9}' rx='2' fill='${x.v>=TGT[2]?'var(--plus)':'var(--lib)'}'/><text class='vl' x='${pl+pw*x.v+4}' y='${y+rh/2+3}'>${pv(x.v)}% ${x.p}/${x.t}</text>`});g+=`<line x1='${tx}' x2='${tx}' y1='${pt-4}' y2='${H-6}' stroke='var(--mut)' stroke-width='1.5' stroke-dasharray='4 3'/>`;return g+'</svg>'+`<div class='leg'><span><i class='sw' style='background:var(--plus)'></i>obiettivo raggiunto</span><span><i class='sw' style='background:var(--lib)'></i>sotto l\u2019obiettivo</span><span>tratteggio = ${pv(TGT[2])}%</span></div>`}
function charts(s){const sets=setList(0),cs=[],add=(t,b)=>cs.push(card(t,b));zi=0;if(s){const T=teamSt(s);add('Efficienza \u00B7 set '+s,bars(ICATS,[{name:'Set '+s,c:SETC[s-1],v:eff(T),sign:1}],1));add('Punti fatti e errori commessi \u00B7 set '+s,bars(['BT','ATT','R','M','Falli'],[{name:'Punti fatti',c:'var(--plus)',v:[T.pBT,T.pATT,null,T.pM,null]},{name:'Errori',c:'var(--minus)',v:[T.eBT,T.eATT,T.eR,T.eM,T.fal]}],0));add('Positivit\u00E0 \u00B7 set '+s,radar(pos(T,s),POSREF));add('Distribuzione palleggio \u00B7 set '+s,court(s))}else{add('Efficienza per set',bars(ICATS,sets.map(k=>({name:'Set '+k,c:SETC[k-1],v:eff(teamSt(k)),sign:1})),1));const ts=sets.map(k=>teamSt(k));add('Punti fatti e errori commessi per set',bars(sets.map(k=>'Set '+k),[{name:'Punti fatti',c:'var(--plus)',v:ts.map(T=>T.pts)},{name:'Errori',c:'var(--minus)',v:ts.map(T=>T.err)}],0));add('Positivit\u00E0 \u00B7 totale',radar(pos(teamSt(0),0),POSREF));add('Distribuzione palleggio \u00B7 totale',court(0))}
add('Andamento del punteggio \u00B7 '+(s?'set '+s:'totale'),trendSvg(trend(s)));add('Errori per tipo \u00B7 '+(s?'set '+s:'per set'),errs(s));add('Ricezione positiva \u00B7 '+(s?'set '+s:'totale'),recv(s));let h=`<div class='grid'>`;for(let k=0;k<cs.length;k+=2)h+=`<div class='cpg'>`+cs[k]+(cs[k+1]||'')+`</div>`;return h+`<div class='card wide'><h3 class='cond'>Indicatori rapidi</h3>${quick(s)}</div></div>`}
function legendAll(){return `<details><summary>Legenda + / \u2212 e indici</summary><dl class='lgt'>`+FUND.map(f=>`<dt>${FN[f]} (${f})</dt>`+LEG[f].map(x=>`<dd style='margin:0'><b>${x[0]}</b></dd><dd style='margin:0'>${x[1]}</dd>`).join('')).join('')+`<dt>Indici</dt><dd style='margin:0'><b>Efficienza</b></dd><dd style='margin:0'>(punti \u2212 errori) / colpi; in verde se sopra l'obiettivo</dd><dd style='margin:0'><b>Efficacia</b></dd><dd style='margin:0'>punti / colpi</dd></dl></details>`}
function line(n,r,num){const sd=r.saldo<0?`<span class='neg'>${r.saldo}</span>`:`<b>${r.saldo}</b>`;const E=eff(r),F=efc(r);const cells=[[sd,''],[r.pBT,'c-p'],[r.pATT,'c-p'],[r.pM,'c-p'],[r.eBT,'c-m'],[r.eATT,'c-m'],[r.eR,'c-m'],[r.eM,'c-m'],[r.fal,'c-m'],[r.nBT,''],[r.nATT,''],[r.nR,''],[r.rP,''],[r.nM,'']];let h=`<td class='stn${num&&num[1]?' lib':''}'>${num?esc(num[0]):''}</td><td class='stk'>${n}</td>`+cells.map(x=>`<td class='${x[0]===0?'z':x[1]}'>${x[0]}</td>`).join('');h+=E.map((x,k)=>`<td class='${k===0?'e1 ':''}${x!==null&&x>=TGT[k]?'okc':''}'>${pc(x,TGT[k])}</td>`).join('');h+=F.map((x,k)=>`<td class='${k===0?'e1':''}'>${pc(x)}</td>`).join('');return h}
/* ---- export ---- */
const today=()=>new Date().toISOString().slice(0,10);
const dIt=()=>{const p=(S.date||today()).split('-');return p[2]+'/'+p[1]+'/'+p[0]};
const fname=ext=>('Scout_'+teamN()+'_vs_'+oppN()+'_'+(S.date||today())).replace(/[^A-Za-z0-9_\-]+/g,'_')+'.'+ext;
function xe(t){return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function xc(v,st){if(v===null||v===undefined||v==='')return '<Cell/>';const sid=st?` ss:StyleID="${st}"`:'';return typeof v==='number'?`<Cell${sid}><Data ss:Type="Number">${Math.round(v*10000)/10000}</Data></Cell>`:`<Cell${sid}><Data ss:Type="String">${xe(v)}</Data></Cell>`}
function xr(cells){return '<Row>'+cells.map(c=>Array.isArray(c)?xc(c[0],c[1]):xc(c)).join('')+'</Row>'}
function xsheet(name,rows,widths){return `<Worksheet ss:Name="${xe(name)}"><Table>`+(widths||[]).map(w=>`<Column ss:Width="${w}"/>`).join('')+rows.join('')+'</Table></Worksheet>'}
function prow(n,ro,r,b){const E=eff(r),F=efc(r),t=b?'b':undefined,p=b?'bp':'p';return xr([[n,t],[ro,t],[r.saldo,t],[r.pBT,t],[r.pATT,t],[r.pM,t],[r.eBT,t],[r.eATT,t],[r.eR,t],[r.eM,t],[r.fal,t],[r.nBT,t],[r.nATT,t],[r.nR,t],[r.rP,t],[r.nM,t],[E[0],p],[E[1],p],[E[2],p],[F[0],p],[F[1],p]])}
function psheet(name,s){const H=['Giocatore','Ruolo','Saldo','Punti BT','Punti ATT','Punti M','Err BT','Err ATT','Err R','Err M','Falli','Tent BT','Tent ATT','Tent R','R +','Tent M','Efficienza BT','Efficienza ATT','Efficienza RIC','Efficacia BT','Efficacia ATT'];const rows=[xr(H.map(x=>[x,'h']))];S.pl.forEach((p,i)=>rows.push(prow(S.names[i],isL(i)?'L':(p.role||''),st(i,s))));rows.push(prow('TOTALE','',teamSt(s),1));return xsheet(name,rows,[90,40].concat(Array(19).fill(52)))}
function buildXls(){const w=won(),sets=[];for(let k=1;k<=S.maxSet;k++)sets.push(k);const rows=[];rows.push(xr([[teamN()+' vs '+oppN(),'t']]));rows.push(xr(['Data',dIt()]));rows.push(xr(['Set vinti',w[0]+'\u2013'+w[1]]));rows.push(xr([]));
rows.push(xr(['Set',teamN(),oppN()].map(x=>[x,'h'])));sets.forEach(k=>rows.push(xr(['Set '+k,S.sc[k-1][0],S.sc[k-1][1]])));rows.push(xr([]));
rows.push(xr(['Squadra','Efficienza BT','Efficienza ATT','Efficienza RIC','Side-out','Break point','Punti fatti','Punti regalati'].map(x=>[x,'h'])));
sets.concat([0]).forEach(k=>{const T=teamSt(k),E=eff(T),Rr=rally(k);rows.push(xr([k?'Set '+k:'Totale',[E[0],'p'],[E[1],'p'],[E[2],'p'],[Rr.so[1]?Rr.so[0]/Rr.so[1]:null,'p'],[Rr.bp[1]?Rr.bp[0]/Rr.bp[1]:null,'p'],T.pts,T.err]))});rows.push(xr([]));
rows.push(xr(['Distribuzione','Banda','Centro','Opposto','Altro'].map(x=>[x,'h'])));sets.concat([0]).forEach(k=>{const d=dist(k),l=k?'Set '+k:'Totale';rows.push(xr([l+' \u00B7 quota'].concat(d.sh.map(x=>[x,'p']))));rows.push(xr([l+' \u00B7 attacchi'].concat(d.n)));rows.push(xr([l+' \u00B7 efficienza'].concat(d.ef.map(x=>[x,'p']))))});
let x='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="h"><Font ss:Bold="1"/><Interior ss:Color="#E6EBEF" ss:Pattern="Solid"/></Style><Style ss:ID="p"><NumberFormat ss:Format="0%"/></Style><Style ss:ID="b"><Font ss:Bold="1"/></Style><Style ss:ID="bp"><Font ss:Bold="1"/><NumberFormat ss:Format="0%"/></Style><Style ss:ID="t"><Font ss:Bold="1" ss:Size="14"/></Style></Styles>';
x+=xsheet('Riepilogo',rows,[120,80,80,80,70,70,70,80]);x+=psheet('Totale',0);sets.forEach(k=>x+=psheet('Set '+k,k));return x+'</Workbook>'}
function download(data,name,type){const b=new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}
function doPdf(){S.view='stat';S.fs=0;render();setTimeout(()=>{try{window.print()}catch(e){}},80)}
function expBox(){return `<div class='card exp' style='margin-top:12px'><h3 class='cond'>Esporta partita</h3><p class='note'>Excel con riepilogo, totale e un foglio per set. PDF: si apre la stampa, scegli \u201CSalva come PDF\u201D.</p><div class='row2'><button type='button' class='act go' data-xls='1'>Esporta Excel</button><button type='button' class='act go' data-pdf='1'>Esporta PDF</button>${histSnap()&&!histSnap().live?`<button type='button' class='act go' data-rop='1'>Riprendi scout</button><button type='button' class='act go del${armHDel?' arm':''}' data-hdel='1'>${armHDel?'Tocca ancora: elimina':'Elimina partita'}</button>`:''}</div></div>`}
function prHead(){const w=won(),r=[];for(let k=1;k<=S.maxSet;k++){const a=S.sc[k-1];if(a[0]||a[1])r.push(a[0]+'\u2013'+a[1])}return `<div class='prh'><b>${esc(teamN())} vs ${esc(oppN())}</b> \u00B7 ${dIt()} \u00B7 Set vinti ${w[0]}\u2013${w[1]}${r.length?' ('+r.join(', ')+')':''}</div>`}
/* ---- storico (solo allenatore) ---- */
async function loadLive(mid,force){const c=NET.hcache[mid];try{const r=await api('GET','/api/data?sv='+NET.sqv+'&v='+(force||!c||!c.live?-1:c.ver)+'&m='+encodeURIComponent(mid));const j=r.j;if(j.live)NET.live=j.live;if(j.gone||(j.state&&j.state.archived)){delete NET.hcache[mid];if(NET.hsel===mid)NET.hsel=null;await pull(true);return true}const st=j.state;if(!st)return false;NET.hcache[mid]={live:1,ver:j.ver,mid,team:st.team,opp:st.opp,date:st.date||'',pl:st.pl,sc:st.sc,ev:st.ev,rally:st.rally||[],subs:st.subs||[],maxSet:st.maxSet||1,set:st.set||1,camp:st.camp||''};return true}catch(e){return false}}
function histSnap(){return S.view==='stat'&&NET.hsel&&NET.hcache[NET.hsel]?NET.hcache[NET.hsel]:null}
function withMatch(h,fn){const K=['pl','team','opp','sc','ev','rally','subs','maxSet','set','date','cr','names'];const bk={};K.forEach(k=>bk[k]=S[k]);Object.assign(S,{pl:h.pl,team:h.team,opp:h.opp,sc:h.sc,ev:h.ev,rally:h.rally||[],subs:h.subs||[],maxSet:h.maxSet||1,set:h.set||1,date:h.date||'',cr:{}});S.names=S.pl.map(p=>p.nick||p.cognome||'?');if(S.fs>S.maxSet)S.fs=0;try{return fn()}finally{Object.assign(S,bk)}}
function histBar(){if(!isCoach())return '';const hs=NET.hist||[],cur=S.phase!=='setup',lv=(NET.live||[]).filter(x=>x.mid!==NET.mid);let h=`<div class='hist'><span class='lbl'>Partita:</span>${cur?`<button type='button' class='chip ${NET.hsel?'':'on'}' data-hs=''>In corso${lv.length?': '+esc(teamN())+' vs '+esc(oppN()):''}</button>`:''}`;lv.forEach(x=>{h+=`<button type='button' class='chip ${NET.hsel===x.mid?'on':''}' data-hs='${esc(x.mid)}'>In corso: ${esc(x.team)} vs ${esc(x.opp)} <small>set ${x.set}</small></button>`});hs.forEach(x=>{const p=(x.date||'').split('-');h+=`<button type='button' class='chip ${NET.hsel===x.mid?'on':''}' data-hs='${esc(x.mid)}'>${esc(x.team)} vs ${esc(x.opp)} <small>${p.length===3?p[2]+'/'+p[1]:''} \u00B7 ${x.won?x.won[0]+'\u2013'+x.won[1]:''}</small></button>`});if(!hs.length&&!lv.length)h+=`<span class='note' style='margin:0'>Nessuna partita nello storico.</span>`;if(hs.length>=10)h+=`<span class='note' style='margin:0'>Altre: menu Squadra \u203A Archivio partite</span>`;return h+`</div>`}
async function loadIdx(){try{const r=await api('GET','/api/history');if(r.ok){NET.idx=r.j.idx||[];NET.hv=r.j.hv}}catch(e){}}
function ensureIdx(){if(NET.idx||NET.idxL)return;NET.idxL=1;loadIdx().then(()=>{NET.idxL=0;if(NET.idx&&S.view==='team')render()})}
function setHv(j){if(typeof j.hv==='number'&&j.hv!==NET.hv){NET.hv=j.hv;NET.idx=null}}
const MESI=['Gennaio','Febbraio','Marzo','Aprile','Maggio','Giugno','Luglio','Agosto','Settembre','Ottobre','Novembre','Dicembre'],GG=['L','M','M','G','V','S','D'];
function archSec(){if(!isCoach())return '';const n=(NET.idx||[]).length;return `<h2 class='cond' style='margin:26px 0 4px;padding-top:14px;border-top:2px solid var(--line)'>Archivio partite</h2><p class='note'>Tutte le partite concluse, per squadra, anno e mese, con il calendario.</p><div class='sqg'><button type='button' class='sqc nw cond' data-ar='1'><b>Apri archivio</b><small>${NET.idx?n+(n===1?' partita':' partite'):'caricamento\u2026'}</small></button></div>`}
const arList=()=>(NET.idx||[]).filter(x=>!arT||String(x.team||'').trim().toLowerCase()===arT);
function archBox(){const A=arList(),tm={};(NET.idx||[]).forEach(x=>{tm[String(x.team||'').trim().toLowerCase()]=x.team});
if(!arY){const d=(A[0]&&A[0].date)||today();arY=+d.slice(0,4);arM=+d.slice(5,7)}
const ym=arY+'-'+String(arM).padStart(2,'0'),days={},ms=A.map(x=>x.date.slice(0,7));A.forEach(x=>{if(x.date.slice(0,7)===ym)(days[x.date]=days[x.date]||[]).push(x)});
let h=`<div class='ar'><div class='hist' style='border:0;margin:0 0 6px;padding:0'><span class='lbl'>Squadra:</span><button type='button' class='chip ${arT?'':'on'}' data-at=''>Tutte</button>`+Object.keys(tm).sort().map(k=>`<button type='button' class='chip ${arT===k?'on':''}' data-at='${esc(k)}'>${esc(tm[k])}</button>`).join('')+`</div>`;
h+=`<div class='arh'><button type='button' class='act sm' data-am='-1' aria-label='Mese precedente' ${ms.some(m=>m<ym)?'':'disabled'}>‹</button><b class='cond'>${MESI[arM-1]} ${arY}</b><button type='button' class='act sm' data-am='1' aria-label='Mese successivo' ${ms.some(m=>m>ym)?'':'disabled'}>›</button><button type='button' class='act sm arc${arCal?' on':''}' data-acal='1' aria-pressed='${arCal}' aria-label='Calendario'>📅</button></div>`;
h+=`<div class='arw${arCal?' co':''}'><div class='cal'><div class='calg'>`+GG.map(g=>`<i>${g}</i>`).join('');
const f=(new Date(arY,arM-1,1).getDay()+6)%7,nd=new Date(arY,arM,0).getDate();for(let i=0;i<f;i++)h+=`<span></span>`;
for(let d=1;d<=nd;d++){const k=ym+'-'+String(d).padStart(2,'0'),n=(days[k]||[]).length;h+=n?`<button type='button' class='cd on${arD===k?' sel':''}' data-ad='${arD===k?'':k}' aria-label='${d} ${MESI[arM-1]}: ${n} partite'>${d}<small>${n>1?n:'•'}</small></button>`:`<span class='cd'>${d}</span>`}
h+=`</div></div><div class='arb'>`;
const L=(arD?A.filter(x=>x.date===arD):A.filter(x=>x.date.slice(0,7)===ym)).sort((a,b)=>a.date<b.date?1:a.date>b.date?-1:0);
if(arD)h+=`<div class='lab'>Partite del ${arD.slice(8)}/${arD.slice(5,7)} <button type='button' class='chip' style='height:28px;font-size:13px' data-ad=''>Tutto il mese</button></div>`;
if(!L.length)h+=`<p class='note'>Nessuna partita in questo periodo.</p>`;
else h+=`<div class='arl'>`+L.map(x=>{const w=x.won,r=w?(w[0]>w[1]?'w':w[0]<w[1]?'l':''):'';return `<button type='button' class='chip arr ${NET.hsel===x.mid?'on':''}' data-hs='${esc(x.mid)}'><b>${esc(x.date.slice(8)+'/'+x.date.slice(5,7))}</b><span>${esc(x.team)} vs ${esc(x.opp)}</span><em class='${r}'>${w?w[0]+'–'+w[1]:''}</em></button>`}).join('')+`</div>`;
return h+`</div></div><p class='note'>${(NET.idx||[]).length} partite in archivio${arT?' (filtro squadra attivo)':''}.</p></div>`}
function applyTgt(){const t=tgtOf(SQ[teamN()]);for(let k=0;k<5;k++)TGT[k]=t[k]}
function tgtBox(){if(!isCoach())return '';const q=S.sq&&SQ[S.sq];if(!q)return `<div class='lab' style='margin-top:14px'>Soglie</div><p class='note'>Salva la squadra per impostarne le soglie.</p>`;const L=['Efficienza battuta','Efficienza attacco','Efficienza ricezione','Side-out','Break point'],t=tgtOf(q);return `<h2 class='cond' style='margin-top:10px'>Efficienze \u00B7 ${esc(S.sq)}</h2><div class='lab' style='margin-top:8px'>Obiettivi in %</div><div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px'>`+L.map((n,i)=>`<label class='fl' style='margin:0'>${n}<input type='text' inputmode='numeric' maxlength='3' data-tg='${i}' data-tk='${esc(S.sq)}' value='${pv(t[i])}'></label>`).join('')+`</div><p class='note'>Valgono per Stats, tabellone e PDF di questa squadra, anche per le partite gi\u00E0 giocate. Efficienza = (punti \u2212 errori) / colpi; side-out e break point = punti vinti quando riceviamo e quando battiamo (rosso se 15 punti sotto la soglia). Il radar mostra BAT, ATT, R, S-O e B-P rispetto a queste soglie.</p>`}
