function rankingsBox(agg){
const players=Object.values(agg).filter(a=>a.r.pts+a.r.err>0||a.r.nR>0);
let h='';
// 1. Classifica punti/errori
h+=`<h3 class='t cond' style='margin-top:18px'>Classifica punti / errori</h3><p class='note'>Chi incide di pi\u00F9 sulla partita. Saldo = punti diretti (ace, attacco, muro) meno errori.</p>`;
const byPts=players.slice().sort((a,b)=>b.r.saldo-a.r.saldo||b.r.pts-a.r.pts);
h+=`<div class='tw'><table><thead><tr><th style='width:28px'></th><th class='stk'>Giocatrice</th><th>Partite</th><th class='gp'>Punti</th><th class='gm'>Errori</th><th>Saldo</th></tr></thead><tbody>`;
byPts.forEach((a,idx)=>{const sd=a.r.saldo<0?`<span class='neg'>${a.r.saldo}</span>`:`<b>${a.r.saldo}</b>`;h+=`<tr><td class='z' style='text-align:center'>${idx+1}</td><td class='stk'>${esc(a.n)}${a.lib?rb('L'):''}</td><td class='z'>${a.g}</td><td class='gp z'>${a.r.pts}</td><td class='gm z'>${a.r.err}</td><td class='z'>${sd}</td></tr>`});
h+=`</tbody></table></div>`;
// 2. Efficienza per fondamentale
h+=`<h3 class='t cond' style='margin-top:18px'>Efficienza per fondamentale</h3><p class='note'>Dove intervenire tatticamente. Efficienza = (punti \u2212 errori) / colpi. Minimo 3 colpi per fondamentale.</p>`;
const withFund=players.filter(a=>a.r.nBT+a.r.nATT+a.r.nR>=3).sort((a,b)=>b.r.saldo-a.r.saldo);
h+=`<div class='tw'><table><thead><tr><th class='stk'>Giocatrice</th><th>Partite</th><th class='ge'>Battuta<small>&gt;${pv(TGT[0])}%</small></th><th class='ge'>Attacco<small>&gt;${pv(TGT[1])}%</small></th><th class='ge'>Ricezione<small>&gt;${pv(TGT[2])}%</small></th></tr></thead><tbody>`;
withFund.forEach(a=>{const E=eff(a.r);h+=`<tr><td class='stk'>${esc(a.n)}${a.lib?rb('L'):''}</td><td class='z'>${a.g}</td>`+E.map((x,k)=>`<td>${pc(x,TGT[k])}</td>`).join('')+`</tr>`});
h+=`</tbody></table></div>`;
// 3. Classifiche per fondamentale
h+=`<h3 class='t cond' style='margin-top:18px'>Classifiche per fondamentale</h3><p class='note'>Le migliori in battuta, attacco e ricezione. Minimo 3 azioni per fondamentale.</p>`;
const fundRank=(list,label,ek,pts,errs,colpi,tgt)=>{if(!list.length)return `<p class='note'>Nessuna con 3+ azioni in ${label.toLowerCase()}.</p>`;let t=`<h4 class='cond' style='margin:10px 0 4px'>${label}</h4><div class='tw'><table><thead><tr><th style='width:24px'></th><th class='stk'>Giocatrice</th><th>Partite</th><th class='ge'>Eff% <small>&gt;${pv(tgt)}%</small></th><th class='gp'>${pts}</th><th class='gm'>${errs}</th><th>${colpi}</th></tr></thead><tbody>`;list.forEach((a,idx)=>{const e=eff(a.r)[ek];t+=`<tr><td class='z' style='text-align:center'>${idx+1}</td><td class='stk'>${esc(a.n)}${a.lib?rb('L'):''}</td><td class='z'>${a.g}</td><td>${pc(e,tgt)}</td><td class='gp z'>${ek===0?a.r.pBT:ek===1?a.r.pATT:a.r.rP}</td><td class='gm z'>${ek===0?a.r.eBT:ek===1?a.r.eATT:a.r.eR}</td><td class='z'>${ek===0?a.r.nBT:ek===1?a.r.nATT:a.r.nR}</td></tr>`});return t+`</tbody></table></div>`};
const byBT=players.filter(a=>a.r.nBT>=3).sort((a,b)=>(eff(b.r)[0]||0)-(eff(a.r)[0]||0));
const byATT=players.filter(a=>a.r.nATT>=3).sort((a,b)=>(eff(b.r)[1]||0)-(eff(a.r)[1]||0));
const byR=players.filter(a=>a.r.nR>=3).sort((a,b)=>(eff(b.r)[2]||0)-(eff(a.r)[2]||0));
h+=fundRank(byBT,'Battuta',0,'Ace','Err','Colpi',TGT[0]);
h+=fundRank(byATT,'Attacco',1,'Punti','Err','Colpi',TGT[1]);
h+=fundRank(byR,'Ricezione',2,'Perf.','Err','Colpi',TGT[2]);
return h}
