function showLogin(err){R.classList.add('auth');$('login').innerHTML=`<div class='lw'><div class='lg' data-logo></div><form class='lf' data-lf='1' autocomplete='on'><h1 class='cond'>Scouty</h1><p>Scout pallavolo \u00B7 accedi con il tuo utente.</p><label>Utente<input name='user' autocomplete='username' autocapitalize='none' required maxlength='40'></label><label>Password<input name='pass' type='password' autocomplete='current-password' required maxlength='200'></label>${err?`<p class='warn' role='alert'>${esc(err)}</p>`:''}<button type='submit' class='act go'>Entra</button></form>${credits(false)}</div>`;applyLogo();const u=$('login').querySelector('input');if(u)u.focus()}
R.addEventListener('submit',async e=>{e.preventDefault();const f=e.target.closest('form');if(!f||!f.dataset.lf)return;const b=f.querySelector('button');b.disabled=true;try{const r=await api('POST','/api/login',{user:f.user.value.trim(),pass:f.pass.value});if(r.ok){NET.me=r.j;await start()}else showLogin(r.status===429?'Troppi tentativi: riprova tra qualche minuto.':'Utente o password errati.')}catch(x){showLogin('Server non raggiungibile.')}});
async function restorePending(){let p=null;try{p=JSON.parse(localStorage.getItem(PK)||'null')}catch(e){}if(!p)return;if(!NET.me||p.u!==NET.me.user||!(NET.live||[]).some(x=>x.mid===p.mid)){clearPending();return}
try{const g=await api('GET','/api/data?v=-1&sv=-1&m='+encodeURIComponent(p.mid));if(g.j.gone||!g.j.state||g.j.ver!==p.base||(g.j.lock&&g.j.lock.alive&&!g.j.lock.mine)){clearPending();note('Azioni non inviate scartate: la partita \u00E8 cambiata sul server.');return}
await openLive(p.mid);if(!NET.mine||NET.mid!==p.mid){clearPending();return}
hydrate({ver:NET.ver,state:JSON.parse(p.state)});NET.dirty=true;SYNC.state='';render();note('Ripristinate le azioni non inviate.');flush()}catch(e){}}
